BEGIN;
-- ===== Subject 21: Public Policy, Government & International Studies
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published');
UPDATE subjects SET about_title='About Public Policy, Government & International Studies', about_body='<p>Public Policy, Government and International Studies explores how governments, institutions and international organisations make and carry out decisions. Areas include international relations, diplomacy, public administration, development, human rights, security and migration.</p><p>Courses build skills in research, policy analysis, writing, negotiation and quantitative methods.</p><p>Studying in a capital city or near international organisations offers internships, networks and guest speakers.</p>', why_title='Why study Public Policy, Government & International Studies?', why_body='<p><strong>Work on real issues.</strong> Graduates contribute to policy on climate, security, health, trade and rights.</p><p><strong>Transferable skills.</strong> Analysis, writing and negotiation are valued across sectors.</p><p><strong>Institutional access.</strong> Studying near governments, think tanks and international bodies helps you build networks.</p><p><strong>Varied careers.</strong> Options include civil service, diplomacy, NGOs, consulting, research and international organisations.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=21 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Public Policy, Government & International Studies', about_body='<p>A Foundation in Public Policy, Government &amp; International Studies. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Public Policy, Government & International Studies?', why_body='<p>Foundation study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Public Policy, Government & International Studies', about_body='<p>A Pathway in Public Policy, Government &amp; International Studies. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Public Policy, Government & International Studies?', why_body='<p>Pathway study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Public Policy, Government & International Studies', about_body='<p>A Diploma in Public Policy, Government &amp; International Studies. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Public Policy, Government & International Studies?', why_body='<p>Diploma study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Public Policy, Government & International Studies', about_body='<p>A Bachelor''s in Public Policy, Government &amp; International Studies. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Public Policy, Government & International Studies?', why_body='<p>Bachelor''s study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Public Policy, Government & International Studies', about_body='<p>A Master''s in Public Policy, Government &amp; International Studies. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Public Policy, Government & International Studies?', why_body='<p>Master''s study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Public Policy, Government & International Studies', about_body='<p>A MBA in Public Policy, Government &amp; International Studies. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Public Policy, Government & International Studies?', why_body='<p>MBA study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Public Policy, Government & International Studies', about_body='<p>A PhD in Public Policy, Government &amp; International Studies. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Public Policy, Government & International Studies?', why_body='<p>PhD study in Public Policy, Government &amp; International Studies lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
-- ===== Subject 22: Economics & Finance
