INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=21 AND status='published'),'about','About Intelligence Studies',NULL,'<p>Intelligence Studies focuses on collecting and analysing information for decision-makers. It sits within Public Policy, Government &amp; International Studies and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND name='Intelligence Studies'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=21 AND status='published'),'why','Why study Intelligence Studies?',NULL,'<p>Intelligence Studies builds specialist skills in collecting and analysing information for decision-makers. Typical graduate roles include intelligence analyst, risk analyst, security researcher. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=21 AND status='published') AND name='Intelligence Studies'));
