INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'destination','United Kingdom',NULL,'<p>Strong life-science research and a large biotech and pharma sector.</p><p>Post-study work: the Graduate Route currently gives 2 years (3 for PhD). For applications made from 1 January 2027 it is being shortened to 18 months for bachelor''s and master''s graduates; PhD stays at 3 years. Tuition for international students is typically £12,000–£40,000 a year depending on course and university.</p>','published',1);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'destination','United States',NULL,'<p>Leading research universities and biotech hubs.</p><p>Graduates can work on OPT for 12 months, with a 24-month STEM extension for eligible degrees. Visa and work-fee rules (OPT and H-1B) are under active review, so check USCIS before planning. International tuition is commonly $25,000–$65,000 a year.</p>','published',2);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'destination','Canada',NULL,'<p>Well-funded research and growing biotech clusters.</p><p>Post-Graduation Work Permit of up to 3 years for eligible programmes (degree graduates are exempt from the field-of-study list). Study permits are capped nationally (408,000 for 2026), but master''s and doctoral students at public institutions are exempt from the cap from 1 January 2026.</p>','published',3);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'destination','Australia',NULL,'<p>Strong in biodiversity, marine and biomedical research.</p><p>Student visa fee is AUD 2,500 from 1 July 2026 and the national planning level is 295,000 new international students (kept for 2027). Graduates can apply for the Temporary Graduate visa (485); length depends on qualification and region.</p>','published',4);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'destination','Germany',NULL,'<p>Strong research institutions and low tuition at most public universities.</p><p>Most public universities charge little or no tuition (Baden-Württemberg charges non-EU students about €1,500 per semester), but you need to show living-cost funds. Graduates can stay up to 18 months to look for work in their field.</p>','published',5);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=24 AND status='published'),'course','Updated in future','Course listings are coming soon',NULL,'published',1);
