INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=25 AND status='published'),'about','About Pharmaceutical Analysis',NULL,'<p>Pharmaceutical Analysis focuses on testing quality, purity and stability of medicines. It sits within Pharmaceutical &amp; Pharmaceutical Sciences and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=25 AND status='published') AND name='Pharmaceutical Analysis'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=25 AND status='published'),'why','Why study Pharmaceutical Analysis?',NULL,'<p>Pharmaceutical Analysis builds specialist skills in testing quality, purity and stability of medicines. Typical graduate roles include analytical scientist, quality-control analyst, lab technician. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=25 AND status='published') AND name='Pharmaceutical Analysis'));
